-- RF1116 V6-side export query (the only place the SQL lives; the lane has no database driver) (RF1116_CN_A_LANE_EXPORT_SPEC_V1 section 2, rev 5 change 2 for industry); @DAY@ is substituted by r2-day-export.sh; one SELECT
SELECT record_id, security_id, business_date, ticker, security_code, exchange, board, asset_class, display_name, name_integrity, listing_date, delisting_date, listing_status, risk_warning_status, first_available_at, ingested_at, source_record_id, revision, schema_version, quality_state, allow_new_risk FROM canonical_security_observation WHERE asset_class = 'STOCK' AND security_id IS NOT NULL AND business_date = '@DAY@' ORDER BY security_id, business_date, revision
